package exercise

import (
	"reflect"
	"testing"
	"time"
)

type wedge struct{ u, v, w int }

func buildUndirected(n int, edges []wedge) [][]Edge {
	adj := make([][]Edge, n)
	for _, e := range edges {
		adj[e.u] = append(adj[e.u], Edge{To: e.v, Weight: e.w})
		adj[e.v] = append(adj[e.v], Edge{To: e.u, Weight: e.w})
	}
	return adj
}

func TestShortestDistancesSmallGraphs(t *testing.T) {
	cases := []struct {
		name  string
		n     int
		edges []wedge
		src   int
		want  []int
	}{
		{
			name:  "five-vertex example",
			n:     5,
			edges: []wedge{{0, 1, 4}, {0, 2, 8}, {1, 2, 3}, {1, 4, 6}, {2, 3, 2}, {3, 4, 10}},
			src:   0,
			want:  []int{0, 4, 7, 9, 10},
		},
		{
			name:  "same graph from a different source",
			n:     5,
			edges: []wedge{{0, 1, 4}, {0, 2, 8}, {1, 2, 3}, {1, 4, 6}, {2, 3, 2}, {3, 4, 10}},
			src:   3,
			want:  []int{9, 5, 2, 0, 10},
		},
		{
			name:  "many cheap hops beat one expensive edge",
			n:     4,
			edges: []wedge{{0, 3, 100}, {0, 1, 1}, {1, 2, 1}, {2, 3, 1}},
			src:   0,
			want:  []int{0, 1, 2, 3},
		},
		{
			name:  "a later, cheaper path must replace an earlier guess",
			n:     4,
			edges: []wedge{{0, 1, 1}, {0, 2, 5}, {1, 3, 1}, {3, 2, 1}},
			src:   0,
			want:  []int{0, 1, 3, 2},
		},
		{
			name:  "parallel edges keep the cheapest",
			n:     2,
			edges: []wedge{{0, 1, 9}, {0, 1, 2}, {0, 1, 5}},
			src:   0,
			want:  []int{0, 2},
		},
		{
			name:  "zero-weight edges",
			n:     3,
			edges: []wedge{{0, 1, 0}, {1, 2, 0}},
			src:   0,
			want:  []int{0, 0, 0},
		},
		{
			name:  "unreachable vertices",
			n:     5,
			edges: []wedge{{0, 1, 3}, {3, 4, 1}},
			src:   0,
			want:  []int{0, 3, -1, -1, -1},
		},
		{
			name: "single vertex",
			n:    1,
			src:  0,
			want: []int{0},
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got := ShortestDistances(c.n, buildUndirected(c.n, c.edges), c.src)
			if !reflect.DeepEqual(got, c.want) {
				t.Errorf("got %v, want %v", got, c.want)
			}
		})
	}
}

func TestShortestDistancesHandlesLargeGraph(t *testing.T) {
	// A long path where every vertex also has a unit-weight shortcut two
	// ahead, so the distance to vertex k is k/2 rounded up. Scanning every
	// vertex for the closest unsettled one on each step would take tens of
	// billions of comparisons here; a priority queue takes a few million.
	const n = 200000
	edges := make([]wedge, 0, 2*n)
	for u := 0; u+1 < n; u++ {
		edges = append(edges, wedge{u, u + 1, 1})
	}
	for u := 0; u+2 < n; u++ {
		edges = append(edges, wedge{u, u + 2, 1})
	}
	adj := buildUndirected(n, edges)

	const budget = 2 * time.Second
	start := time.Now()
	got := ShortestDistances(n, adj, 0)
	elapsed := time.Since(start)

	if len(got) != n {
		t.Fatalf("got %d distances, want %d", len(got), n)
	}
	for k := 0; k < n; k++ {
		if want := (k + 1) / 2; got[k] != want {
			t.Fatalf("distance to vertex %d: got %d, want %d", k, got[k], want)
		}
	}
	if elapsed > budget {
		t.Fatalf("took %v on a graph of %d vertices and %d edges, over the %v budget: always take the closest unsettled vertex from a priority queue instead of scanning every vertex for it", elapsed, n, len(edges), budget)
	}
}

