package exercise

import "container/heap"

type Edge struct {
	To     int
	Weight int
}

type item struct {
	vertex int
	dist   int
}

type minHeap []item

func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i].dist < h[j].dist }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(item)) }
func (h *minHeap) Pop() any {
	old := *h
	last := old[len(old)-1]
	*h = old[:len(old)-1]
	return last
}

func ShortestDistances(n int, adj [][]Edge, src int) []int {
	dist := make([]int, n)
	for i := range dist {
		dist[i] = -1
	}
	dist[src] = 0

	h := &minHeap{{vertex: src, dist: 0}}
	for h.Len() > 0 {
		cur := heap.Pop(h).(item)
		if cur.dist > dist[cur.vertex] {
			continue
		}
		for _, e := range adj[cur.vertex] {
			next := cur.dist + e.Weight
			if dist[e.To] == -1 || next < dist[e.To] {
				dist[e.To] = next
				heap.Push(h, item{vertex: e.To, dist: next})
			}
		}
	}
	return dist
}
